sp_widget.client_script:
function($scope, $timeout) {
  var c = this;
  /* I6: Idea-lifecycle states (value -> chip slug). */
  var SLUGS = {'1': 'submitted', '-2': 'need_info', '-1': 'under_review', '2': 'in_backlog',
               '4': 'planned', '5': 'in_development', '3': 'completed', '7': 'unlikely',
               '9': 'cancelled', '8': 'duplicate'};
  /* I12: state-context sub-notes - the I6 register VERBATIM (same copy
     ptag_myeng_w's CONTEXT speaks; one register app-wide). */
  var NOTES = {
    '1':  'Request received and queued for triage.',
    '-1': 'PTAG is validating scope and fit.',
    '2':  'Accepted and waiting for capacity.',
    '4':  'Scheduled with an owner and a timeline.',
    '5':  'Work in flight with the assigned team.',
    '3':  'Engagement delivered and closed.',
    '-2': 'Review is paused until you add the requested details.',
    '7':  'Not moving forward after PTAG review.',
    '8':  'Already tracked under another request.',
    '9':  'Withdrawn before completion.'
  };

  var stats = (c.data && c.data.stats) || { total: 0, by_state: [] };
  var counts = {}, labels = {};
  var i, row;
  for (i = 0; i < (stats.by_state || []).length; i++) {
    row = stats.by_state[i];
    counts[String(row.state)] = row.count || 0;
    labels[String(row.state)] = row.label || '';
  }

  c.total = stats.total || 0;
  c.practices = stats.practices || 0;
  c.routes = stats.routes || 0;
  c.active = 0;
  var activeKeys = ['1', '-2', '-1', '2', '4', '5'];
  for (i = 0; i < activeKeys.length; i++) { c.active += counts[activeKeys[i]] || 0; }

  /* Live pipeline rows: the six happy-path lifecycle states always (zero-
     filled); attention + terminal branches only when they hold records. */
  c.pipe = [];
  var happy = ['1', '-1', '2', '4', '5', '3'];
  for (i = 0; i < happy.length; i++) {
    c.pipe.push({ slug: SLUGS[happy[i]], label: labels[happy[i]], count: counts[happy[i]] || 0,
                  note: NOTES[happy[i]] || '' });
  }
  var branch = ['-2', '7', '9', '8'];
  for (i = 0; i < branch.length; i++) {
    if (counts[branch[i]]) {
      c.pipe.push({ slug: SLUGS[branch[i]], label: labels[branch[i]], count: counts[branch[i]],
                    note: NOTES[branch[i]] || '' });
    }
  }

  /* ===== I13 R1: scroll navigation - dot-rail active tracking + hero scroll cue ===== */
  c.rail = [
    { id: 'pt-sec-top',  label: 'Top' },
    { id: 'pt-sec-how',  label: 'How it works' },
    { id: 'pt-sec-what', label: 'What you get' },
    { id: 'pt-sec-cta',  label: 'Submit' }
  ];
  c.activeSec = 'pt-sec-top';
  /* I16d: TWO static Explore controls. cueUp / cueDown are pure "is travel in
     this direction possible" flags, recomputed from real scroll position, so a
     control is only ever on screen when it has somewhere to go. */
  c.cueUp = false;
  c.cueDown = false;
  c.cueGo = function(dir) {
    var i, idx = 0;
    for (i = 0; i < c.rail.length; i++) {
      if (c.rail[i].id === c.activeSec) { idx = i; break; }
    }
    var next = (dir === 'up') ? Math.max(idx - 1, 0)
                              : Math.min(idx + 1, c.rail.length - 1);
    c.scrollTo(c.rail[next].id);
  };
  function _scrollerFor(node) {
    /* the SP portal scrolls an inner container (section.sp-scroll), NOT window */
    var n = node ? node.parentElement : null;
    while (n) {
      var s; try { s = window.getComputedStyle(n); } catch (e) { s = null; }
      if (s && /(auto|scroll)/.test(s.overflowY) && n.scrollHeight > n.clientHeight + 4) { return n; }
      n = n.parentElement;
    }
    return null;
  }
  function _cueScroller() {
    return document.querySelector('.sp-scroll')
        || _scrollerFor(document.getElementById('pt-sec-top') || document.body)
        || document.scrollingElement || document.documentElement;
  }
  function _syncCue() {
    var sc = _cueScroller();
    if (!sc) { return; }
    var st = sc.scrollTop || 0;
    var max = (sc.scrollHeight || 0) - (sc.clientHeight || 0);
    var up = false, down = false;
    if (max >= 40) {                 /* a page that cannot scroll gets neither */
      up = st > 8;                   /* page above  -> offer the top control */
      down = st < max - 12;          /* page below  -> offer the bottom control */
    }
    if (up !== c.cueUp || down !== c.cueDown) {
      $timeout(function() { c.cueUp = up; c.cueDown = down; });
    }
  }
  c.scrollTo = function(id) {
    /* I14 R1: the first rail item ("Top") goes to the ABSOLUTE top (scrollTop 0
       - hero + fixed header fully visible), not the section offset that
       scroll-margin-top leaves. The SP portal scrolls an inner .sp-scroll
       container, so zero THAT (plus window/scrollingElement fallbacks). */
    if (id === (c.rail[0] && c.rail[0].id)) {
      var targets = [document.querySelector('.sp-scroll'), _scrollerFor(document.getElementById(id) || document.body)];
      for (var t = 0; t < targets.length; t++) {
        if (targets[t]) { try { targets[t].scrollTo({ top: 0, left: 0, behavior: 'smooth' }); } catch (e) { targets[t].scrollTop = 0; } }
      }
      try { window.scrollTo({ top: 0, left: 0, behavior: 'smooth' }); } catch (e2) {}
      try { if (document.scrollingElement) { document.scrollingElement.scrollTop = 0; } } catch (e3) {}
      return;
    }
    var el = document.getElementById(id);
    if (el && el.scrollIntoView) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
  };
  var _io = null, _onScroll = null;
  $timeout(function() {
    try {
      if (window.IntersectionObserver) {
        _io = new IntersectionObserver(function(entries) {
          var best = null;
          for (var k = 0; k < entries.length; k++) { if (entries[k].isIntersecting) { best = entries[k].target.id; } }
          if (best) {
            $timeout(function() { c.activeSec = best; });
          }
        }, { rootMargin: '-45% 0px -50% 0px', threshold: 0 });
        for (var j = 0; j < c.rail.length; j++) {
          var s = document.getElementById(c.rail[j].id);
          if (s) { _io.observe(s); }
        }
      }
      /* I16: the SP portal scrolls an inner section.sp-scroll container, NOT
         window, so the sync MUST be bound to that element or it never fires. */
      _onScroll = function() { _syncCue(); };
      var _sc = _cueScroller();
      if (_sc && _sc.addEventListener) { _sc.addEventListener('scroll', _onScroll, { passive: true }); }
      window.addEventListener('scroll', _onScroll, { passive: true });
      window.addEventListener('resize', _onScroll, { passive: true });
      _syncCue();
    } catch (e) {}
  }, 0);
  if ($scope && $scope.$on) {
    $scope.$on('$destroy', function() {
      try { if (_io) { _io.disconnect(); } } catch (e) {}
      try { if (_onScroll) { var _s2 = _cueScroller(); if (_s2 && _s2.removeEventListener) { _s2.removeEventListener('scroll', _onScroll); } window.removeEventListener('scroll', _onScroll); window.removeEventListener('resize', _onScroll); } } catch (e2) {}
    });
  }

  /* ===== I13 R2: track by number -> ?id=ptag_status&number= (client-side validate + shake) ===== */
  c.num = '';
  c.numErr = false;
  c.numTouch = function() { if (c.numErr) { c.numErr = false; } };
  c.goNumber = function() {
    var v = String(c.num || '').trim().toUpperCase();
    c.num = v;
    /* I14 R6: accept real * wildcards - charset PTAG/digits/*, must hold at
       least one non-* fragment; ** collapses to *. No * -> exact (identical to
       I13). The pattern rides ?number= to My Engagements, which translates it
       to the LIKE-fragment query and renders a filtered list. */
    if (!/^[PTAG0-9*]+$/.test(v) || v.replace(/\*/g, '') === '') {
      c.numErr = false;                       /* reset to retrigger the shake */
      $timeout(function() { c.numErr = true; });
      return;
    }
    v = v.replace(/\*{2,}/g, '*');
    if (v.indexOf('*') === -1 && !/^PTAG\d{4,}$/.test(v)) {
      c.numErr = false;
      $timeout(function() { c.numErr = true; });
      return;
    }
    c.num = v;
    c.numErr = false;
    window.location.assign('?id=ptag_status&number=' + encodeURIComponent(v));
  };
}

sp_widget.script:
(function() {
  /* Stats strip + live pipeline: counts by state via GlideAggregate.
     I6: state set = the intake app's Idea-lifecycle choices (mapped in i6_03;
     labels mirror the live sys_choice set). */
  var LABELS = {'1':'Submitted','-2':'Need more information','-1':'Under Review',
                '2':'In Backlog','4':'Planned','5':'In Development','3':'Completed',
                '7':'Unlikely to implement','9':'Cancelled','8':'Duplicate'};
  var ORDER = ['1','-2','-1','2','4','5','3','7','9','8'];
  data.stats = { total: 0, by_state: [] }; // stats strip removed I11; by_state feeds the pipeline panel only
  var counts = {};
  var ga = new GlideAggregate('x_snc_ptag_engage_engagement_request');
  ga.addQuery('opened_by', gs.getUserID()); // I11: viewer-scoped per Jon
  ga.addAggregate('COUNT');
  ga.groupBy('state');
  ga.query();
  while (ga.next()) {
    var st = String(ga.getValue('state') || '');
    var n = parseInt(ga.getAggregate('COUNT'), 10) || 0;
    data.stats.total += n;
    counts[st] = n;
  }
  for (var i = 0; i < ORDER.length; i++) {
    var v = ORDER[i];
    data.stats.by_state.push({ state: v, label: LABELS[v] || ('State ' + v), count: counts[v] || 0 });
  }

  /* I5: coverage stats count the intake app lookup tables (read-only) */
  function refCount(t) {
    try {
      var ga2 = new GlideAggregate(t);
      ga2.addAggregate('COUNT');
      ga2.query();
      return ga2.next() ? (parseInt(ga2.getAggregate('COUNT'), 10) || 0) : 0;
    } catch (e) { return 0; }
  }
})();
